import UIKit
final class RemoteController: UIViewController {
    private(set) var percent = 0
    @objc func apply(_ sender: UISlider) { percent = Int(sender.value) }
}
let controller = RemoteController()
controller.loadViewIfNeeded()
let slider = UISlider()
controller.view.addSubview(slider)
slider.addTarget(
    nil, action: #selector(RemoteController.apply(_:)), for: .valueChanged
)
assert(slider.next === controller.view)
assert(controller.view.next === controller)
slider.value = 60
controller.apply(slider)
assert(controller.percent == 60)

Настроен новый элемент пульта — slider. Ручной вызов проверяет обработчик и явные next-связи; реальный action-поиск без UIWindow здесь не запускается.
